/**
 * The shipped catalog, loaded from generated JSON. Import the card list from
 * the `./data` subpath so core users do not pay for it:
 *
 * ```ts
 * import { cards, sets, catalogVersion } from "@dierkens.dev/ptcg-decklist-tools/data";
 * ```
 *
 * The set index and the small archetype table are also used by core functions.
 * Cards and sets are generated by `pnpm run catalog` from a pinned public TCGdex
 * dump; archetypes are snapshotted by `pnpm run archetypes` from Limitless. Both
 * builds validate their data; this module only gives it the public types.
 */

import cardsJson from "./data/cards.json" with { type: "json" };
import versionJson from "./data/version.json" with { type: "json" };

import { sets } from "./sets.js";
import type { Catalog, CatalogCard } from "./types.js";

export type { Catalog, CatalogArchetype, CatalogCard, CatalogSet } from "./types.js";
export { archetypes } from "./archetypes.js";
export { sets } from "./sets.js";

/** The build date of this catalog, `YYYY-MM-DD`. Store it beside a hash. */
export const catalogVersion: string = versionJson.version;

/** Every Live-addressable printing, in set and collector-number order. */
export const cards: readonly CatalogCard[] = cardsJson as readonly CatalogCard[];

/** The whole catalog in one object, ready for `normalizeDecklist(parsed, { catalog })`. */
export const catalog: Catalog = { cards, sets, catalogVersion };
